const acorn=require('acorn');
const {JSDOM,VirtualConsole}=require('jsdom');

const repo=process.env.GH_REPOSITORY,token=process.env.GH_TOKEN,path='siza-mobile-test/index.html';
const headers={'Accept':'application/vnd.github+json','Authorization':`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'};
const api=`https://api.github.com/repos/${repo}/contents/${path}`;
const assert=(v,m)=>{if(!v)throw new Error(m)};
async function getFile(p){const r=await fetch(`https://api.github.com/repos/${repo}/contents/${p}?ref=main`,{headers});if(!r.ok)throw new Error(`${p}: GET ${r.status}`);const f=await r.json();return{sha:f.sha,text:Buffer.from(f.content.replace(/\n/g,''),'base64').toString('utf8')}}
function parse(html){const so=html.lastIndexOf('<script>'),sc=html.indexOf('</script>',so);assert(so>=0&&sc>so,'main script not found');const start=so+8,code=html.slice(start,sc),ast=acorn.parse(code,{ecmaVersion:'latest'}),decl=[];function walk(n){if(!n||typeof n!=='object')return;if(n.type==='FunctionDeclaration'&&n.id)decl.push(n);for(const[k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==='object'&&v.type)walk(v)}}walk(ast);return{start,sc,code,decl}}
function inlineCore(html,files){let out=html;for(const[name,text]of [['card-effects.js',files.effects],['card-schema.js',files.schema],['cards.js',files.cards],['card-renderer.js',files.renderer]]){const tag=`<script src="../siza-core/${name}"></script>`;assert(out.includes(tag),`Missing core tag ${name}`);out=out.replace(tag,`<script>${text}</script>`)}return out}
function makeDom(html,label){const vc=new VirtualConsole();vc.on('jsdomError',e=>console.error(`[JSDOM ${label}]`,e.message));return new JSDOM(html,{runScripts:'dangerously',url:'https://siza.local/siza-mobile-test/',virtualConsole:vc})}
function report(html){const p=parse(html),m=new Map();for(const n of p.decl)m.set(n.id.name,(m.get(n.id.name)||0)+1);return{total:p.decl.length,dupes:[...m.entries()].filter(([,c])=>c>1).sort((a,b)=>a[0].localeCompare(b[0]))}}
function cleanup(html){const p=parse(html),names=['arenaMenuHtml','fieldCardFocusHtml','matchCardFocus','matchCardMini','removeBattlefieldAt','renderMatchV600'],cuts=[];for(const name of names){const nodes=p.decl.filter(n=>n.id.name===name).sort((a,b)=>a.start-b.start);assert(nodes.length===2,`${name}: expected 2, got ${nodes.length}`);cuts.push([nodes[0].start,nodes[0].end,name])}let code=p.code;for(const[start,end,name]of cuts.sort((a,b)=>b[0]-a[0]))code=code.slice(0,start)+`/* canonicalized ${name}: earlier declaration removed */`+code.slice(end);return html.slice(0,p.start)+code+html.slice(p.sc)}

(async()=>{
 const index=await getFile(path),files={effects:(await getFile('siza-core/card-effects.js')).text,schema:(await getFile('siza-core/card-schema.js')).text,cards:(await getFile('siza-core/cards.js')).text,renderer:(await getFile('siza-core/card-renderer.js')).text};console.log('Current Mobile blob '+index.sha);
 const before=report(index.text);assert(before.dupes.length===6,'Expected exactly 6 duplicate names before final cleanup: '+JSON.stringify(before.dupes));
 const html=cleanup(index.text),after=report(html);assert(after.dupes.length===0,'Duplicate declarations remain: '+JSON.stringify(after.dupes));assert(after.total===before.total-6,`Expected 6 declarations removed, got ${before.total-after.total}`);console.log(`Duplicate names ${before.dupes.length} -> 0; declarations ${before.total} -> ${after.total}`);
 const marker='window.SIZA={';assert(index.text.includes(marker)&&html.includes(marker),'SIZA marker missing');
 const probe=`window.__RENDER_TEST__={createMatch,setMatch:m=>state.match=m,setNav:v=>state.arenaNavOpen=v,arenaMenuHtml,matchCardMini,matchCardFocus,fieldCardFocusHtml,removeBattlefieldAt,renderMatchV600};\n`;
 const oldDom=makeDom(inlineCore(index.text,files).replace(marker,probe+marker),'old'),newDom=makeDom(inlineCore(html,files).replace(marker,probe+marker),'new');oldDom.window.setTimeout=()=>0;newDom.window.setTimeout=()=>0;
 function setup(dom){const H=dom.window.__RENDER_TEST__,M=H.createMatch(false,'prepare');H.setMatch(M);H.setNav(true);M.active='player';M.phase='Main';M.pendingChoice=null;M.pendingEquip=null;M.pendingResolution=false;M.responseWindow=null;M.stack=[];M.player.hand=['spark'];M.player.library=['mist'];M.player.graveyard=[];M.player.exile=[];M.player.battlefield=['servitor','ignimite'];M.player.powerCounters=[0,1];M.player.summonedOn=[0,0];M.player.exhausted=[1];M.player.equipment=[{id:'tideblade',target:0}];M.player.artifacts=[];M.player.crystals={U:2,R:1};M.player.combatUsed=false;M.enemy.hand=['mist'];M.enemy.library=['spark'];M.enemy.graveyard=[];M.enemy.exile=[];M.enemy.battlefield=['watcher'];M.enemy.powerCounters=[0];M.enemy.summonedOn=[0];M.enemy.exhausted=[];M.enemy.equipment=[];M.enemy.artifacts=[];M.ui={hand:0,creature:0,attackMode:false,attackers:[],fieldFocus:{owner:'player',index:0}};return{H,M}}
 function uiSnap(dom){const{H}=setup(dom);return{menu:H.arenaMenuHtml(),mini:H.matchCardMini('servitor','player',0),hand:H.matchCardFocus(),field:H.fieldCardFocusHtml(),match:H.renderMatchV600()}}
 const a=uiSnap(oldDom),b=uiSnap(newDom);for(const k of Object.keys(a))assert(a[k]===b[k],`${k} render changed after canonicalization`);assert(a.mini.includes('+2/+0')&&a.hand.includes('Chispa del Estuario')&&a.field.includes('Servidor Ahogado')&&a.match.includes('Siza Arena'),'Canonical render snapshot unexpected');console.log('PASS canonical render surfaces unchanged');
 function removeSnap(dom){const H=dom.window.__RENDER_TEST__,M=H.createMatch(false,'prepare');H.setMatch(M);const P=M.player;P.hand=[];P.graveyard=[];P.battlefield=['servitor','ignimite'];P.powerCounters=[0,2];P.summonedOn=[1,1];P.exhausted=[1];P.equipment=[{id:'tideblade',target:1}];M.ui={hand:-1,creature:0,attackMode:true,attackers:[0,1],fieldFocus:{owner:'player',index:1}};const id=H.removeBattlefieldAt(P,0,'hand');return{id,hand:[...P.hand],graveyard:[...P.graveyard],battlefield:[...P.battlefield],power:[...P.powerCounters],summoned:[...P.summonedOn],exhausted:[...P.exhausted],equipment:P.equipment.map(e=>({...e})),ui:JSON.parse(JSON.stringify(M.ui))}}
 const ra=removeSnap(oldDom),rb=removeSnap(newDom);assert(JSON.stringify(ra)===JSON.stringify(rb),'removeBattlefieldAt behavior changed');assert(ra.id==='servitor'&&ra.hand[0]==='servitor'&&ra.graveyard.length===0&&ra.battlefield[0]==='ignimite'&&ra.power[0]===2&&ra.exhausted[0]===0&&ra.equipment[0].target===0&&ra.ui.fieldFocus.index===0,'Canonical battlefield removal contract unexpected');console.log('PASS battlefield removal/index maintenance unchanged');
 const ao=oldDom.window.SIZA.runArenaCriticalV071(),an=newDom.window.SIZA.runArenaCriticalV071();assert(ao.passed===ao.total&&an.passed===an.total,'Arena critical regression');console.log(`PASS Arena old ${ao.passed}/${ao.total} -> new ${an.passed}/${an.total}`);oldDom.window.close();newDom.window.close();
 const w=await fetch(api,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({message:'Canonicalize final Arena render declarations',content:Buffer.from(html,'utf8').toString('base64'),sha:index.sha,branch:'main'})});if(!w.ok)throw new Error(`PUT ${w.status}: ${await w.text()}`);const out=await w.json();console.log('COMMIT '+out.commit.sha);
})().catch(e=>{console.error(e.stack||e.message);process.exit(1)});
